package io.github.iamr0s.carvex.carplay.core

import org.junit.Assert.*
import org.junit.Test
import java.io.*
import java.util.Properties

/** Golden bytes are published E16 synthetic vectors, not generated by the implementation. */
class PairSetupSrpTest {
    private val vectors=Properties().apply{load(PairSetupSrpTest::class.java.getResourceAsStream("/security-synthetic-vectors.properties"))}
    private fun bytes(name:String,key:String)=vectors.getProperty("$name.$key").chunked(2).map{it.toInt(16).toByte()}.toByteArray()

    @Test fun fullWidthAndShortPublicKeyMatchIndependentProofs(){
        for(name in listOf("full-width","leading-zero-A"))PairSetupSrp(bytes(name,"a")).use{srp->
            assertArrayEquals(bytes(name,"A"),srp.public)
            srp.respond(bytes(name,"salt"),bytes(name,"B"),vectors.getProperty("$name.password").toByteArray()).use{proof->
                assertArrayEquals(bytes(name,"K"),proof.key)
                assertArrayEquals(bytes(name,"clientProof"),proof.client)
                assertArrayEquals(bytes(name,"serverProof"),proof.server)
                if(name=="leading-zero-A"){
                    assertEquals(383,srp.public.size)
                    assertFalse(proof.client.contentEquals(bytes(name,"paddedProof")))
                }
            }
        }
    }

    @Test fun completeSetupMatchesBothPublishedM1ThroughM6Sequences(){
        for(name in listOf("full-width","leading-zero-A")){
            var pending=ByteArrayInputStream(byteArrayOf())
            val input=object:InputStream(){override fun read()=pending.read();override fun read(b:ByteArray,off:Int,len:Int)=pending.read(b,off,len)}
            var stage=1
            val output=object:ByteArrayOutputStream(){override fun flush(){
                val request=RtspWire.read(ByteArrayInputStream(toByteArray()));reset()
                assertArrayEquals("$name M$stage",bytes(name,"M$stage"),request.body)
                val reply=ByteArrayOutputStream().also{RtspWire.write(it,"RTSP/1.0 200 OK",mapOf("CSeq" to request.headers["cseq"]!!),bytes(name,"M${stage+1}"))}
                pending=ByteArrayInputStream(reply.toByteArray());stage+=2
            }}
            val identity=PairIdentity(bytes(name,"Controller.identifier").toString(Charsets.US_ASCII),bytes(name,"Controller.seed"))
            val homeKit=HomeKit(RtspClient(input,output),identity){PairSetupSrp(bytes(name,"a"))}
            val peer=homeKit.setup(setupCode=vectors.getProperty("$name.password").toByteArray())
            assertEquals(7,stage)
            assertArrayEquals(bytes(name,"Accessory.identifier"),peer.identifier)
            assertArrayEquals(bytes(name,"Accessory.publicKey"),peer.public)
        }
    }

    @Test fun invalidGroupSaltAndClosedPrivateStateAreRejected(){
        val name="full-width"
        PairSetupSrp(bytes(name,"a")).use{srp->
            for(server in listOf(byteArrayOf(),byteArrayOf(0),ByteArray(385){1},ByteArray(384){-1}))
                assertThrows(IllegalArgumentException::class.java){srp.respond(bytes(name,"salt"),server,byteArrayOf(1))}
            assertThrows(IllegalArgumentException::class.java){srp.respond(ByteArray(15),bytes(name,"B"),byteArrayOf(1))}
            srp.close()
            assertThrows(IllegalArgumentException::class.java){srp.respond(bytes(name,"salt"),bytes(name,"B"),byteArrayOf(1))}
        }
    }

    @Test fun explicitV11DialectMatchesIndependentPaddedProof(){
        for(name in listOf("full-width","leading-zero-A"))
            PairSetupSrp(bytes(name,"a"),PairSetupProof.EXPERIMENTAL_V11_PADDED).use{srp->
                val a=bytes(name,"A")
                assertArrayEquals(ByteArray(384-a.size)+a,srp.public)
                srp.respond(bytes(name,"salt"),bytes(name,"B"),vectors.getProperty("$name.password").toByteArray()).use{proof->
                    assertArrayEquals(bytes(name,"K"),proof.key)
                    assertArrayEquals(bytes(name,"paddedProof"),proof.client)
                }
            }
    }
}
